import{_ as a,o as t,c as i,a6 as n}from"./chunks/framework.BrkgobfX.js";const c=JSON.parse('{"title":"HuggingFace 到底是什么","description":"Hub、Python 库、付费服务三层结构，以及它们各自解决什么问题。","frontmatter":{"title":"HuggingFace 到底是什么","description":"Hub、Python 库、付费服务三层结构，以及它们各自解决什么问题。","source":"https://daiw.org/manual/huggingface/what-is-huggingface"},"headers":[],"relativePath":"manual/llm/huggingface/what-is-huggingface.md","filePath":"manual/llm/huggingface/what-is-huggingface.md"}'),e={name:"manual/llm/huggingface/what-is-huggingface.md"};function l(r,s,p,d,h,o){return t(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="huggingface-到底是什么" tabindex="-1">HuggingFace 到底是什么 <a class="header-anchor" href="#huggingface-到底是什么" aria-label="Permalink to &quot;HuggingFace 到底是什么&quot;">​</a></h1><blockquote><p>Hub、Python 库、付费服务三层结构，以及它们各自解决什么问题。</p></blockquote><p>“HuggingFace”这个名字被用来指三样不同的东西，混在一起讲很容易糊涂。先把它们分开。</p><h2 id="三层" tabindex="-1">三层 <a class="header-anchor" href="#三层" aria-label="Permalink to &quot;三层&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌───────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 服务层   Inference Endpoints / Spaces / PRO    │  花钱买算力与托管</span></span>
<span class="line"><span>├───────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 库层     transformers / datasets / peft / trl  │  在你的机器上用</span></span>
<span class="line"><span>│          huggingface_hub / accelerate / hf CLI │</span></span>
<span class="line"><span>├───────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ Hub      模型 / 数据集 / Spaces 的托管仓库      │  免费，本质是加了大文件支持的 Git</span></span>
<span class="line"><span>└───────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><strong>绝大多数人只需要下面两层，而且都是免费的。</strong> 第 6 部分才会讲服务层值不值得买。</p><h2 id="hub-一堆-git-仓库" tabindex="-1">Hub：一堆 Git 仓库 <a class="header-anchor" href="#hub-一堆-git-仓库" aria-label="Permalink to &quot;Hub：一堆 Git 仓库&quot;">​</a></h2><p>这是最容易被低估的一点——<strong>Hub 上每个模型仓库就是一个 Git 仓库</strong>，只是用 Git LFS（以及新版的 Xet 分块存储后端）存大文件。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://huggingface.co/Qwen/Qwen3-8B</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>真的能这么 clone。这意味着：</p><ul><li>有完整的<strong>提交历史</strong>，可以 checkout 到某个旧版本</li><li>有<strong>分支和 tag</strong>（很多模型用分支放不同量化版本）</li><li>有 <strong>PR 机制</strong>（Hub 上叫 Discussion）</li></ul><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 拉取某个特定 revision，而不是最新的 main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> download</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Qwen/Qwen3-8B</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --revision</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> refs/pr/1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>“模型会变”这件事常被忽略。</strong> 模型作者随时可能推新 commit 修 bug、换 tokenizer、改 config。你昨天下的和今天下的可能不一样。</p><p>生产环境务必<strong>钉住 revision</strong>：</p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> transformers </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AutoModel</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AutoModel.from_pretrained(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;org/model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">revision</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;a1b2c3d&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>用 commit hash，不要用分支名——分支会移动。</p></div><h3 id="三类仓库" tabindex="-1">三类仓库 <a class="header-anchor" href="#三类仓库" aria-label="Permalink to &quot;三类仓库&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>URL 前缀</th><th>装什么</th></tr></thead><tbody><tr><td><strong>Models</strong></td><td><code>huggingface.co/&lt;org&gt;/&lt;name&gt;</code></td><td>权重、配置、tokenizer</td></tr><tr><td><strong>Datasets</strong></td><td><code>huggingface.co/datasets/...</code></td><td>训练与评测数据</td></tr><tr><td><strong>Spaces</strong></td><td><code>huggingface.co/spaces/...</code></td><td>可运行的 Demo（Gradio / Streamlit / Docker）</td></tr></tbody></table><p>三者的下载方式基本一致，只是 API 里要指定 <code>repo_type</code>。</p><h2 id="库层-各管一段" tabindex="-1">库层：各管一段 <a class="header-anchor" href="#库层-各管一段" aria-label="Permalink to &quot;库层：各管一段&quot;">​</a></h2><p>刚接触时最容易迷惑的是“这么多库，我该用哪个”。它们的分工其实很清楚：</p><table tabindex="0"><thead><tr><th>库</th><th>干什么</th><th>什么时候用</th></tr></thead><tbody><tr><td><strong><code>huggingface_hub</code></strong></td><td>只管<strong>上传下载</strong>，不碰模型</td><td>想拿文件时</td></tr><tr><td><strong><code>transformers</code></strong></td><td>加载模型、跑推理、训练</td><td>主力库</td></tr><tr><td><strong><code>datasets</code></strong></td><td>加载与处理数据集</td><td>训练前</td></tr><tr><td><strong><code>accelerate</code></strong></td><td>多卡 / 混合精度 / 设备分配</td><td>显存不够或多卡时</td></tr><tr><td><strong><code>peft</code></strong></td><td>LoRA 等参数高效微调</td><td>微调</td></tr><tr><td><strong><code>trl</code></strong></td><td>SFT / DPO 等训练流程封装</td><td>微调</td></tr><tr><td><strong><code>safetensors</code></strong></td><td>安全的权重序列化格式</td><td>通常被自动调用</td></tr><tr><td><strong><code>tokenizers</code></strong></td><td>高性能分词（Rust 实现）</td><td>通常被自动调用</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>只想下载文件的话，别装 <code>transformers</code>。</strong></p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> huggingface_hub</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 几 MB</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> transformers</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 会拖进 torch，几 GB</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>很多脚本只是为了 <code>snapshot_download</code> 一个文件就 <code>import transformers</code>，白白拉几个 G 的依赖。<strong>分清“拿文件”和“跑模型”是两件事。</strong></p></div><h2 id="一个最小完整例子" tabindex="-1">一个最小完整例子 <a class="header-anchor" href="#一个最小完整例子" aria-label="Permalink to &quot;一个最小完整例子&quot;">​</a></h2><p>从零到跑起来，四行：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> transformers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> transformers </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pipeline</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pipe </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pipeline(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;text-generation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">model</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Qwen/Qwen3-0.6B&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(pipe(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;介绍一下你自己&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">max_new_tokens</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;generated_text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>第一次运行会自动下载模型到本地缓存（<code>~/.cache/huggingface/hub</code>），之后从缓存读。</p><p><strong><code>pipeline</code> 是最省事的入口</strong>，但它把很多东西藏起来了（设备选择、精度、量化）。真要控制这些，见 <a href="/Front2Full/manual/llm/huggingface/transformers-serving">transformers 部署</a>。</p><h2 id="模型页怎么读" tabindex="-1">模型页怎么读 <a class="header-anchor" href="#模型页怎么读" aria-label="Permalink to &quot;模型页怎么读&quot;">​</a></h2><p>打开任意一个模型页，值得先看的四处：</p><table tabindex="0"><thead><tr><th>位置</th><th>看什么</th></tr></thead><tbody><tr><td><strong>Model card</strong>（首屏正文）</td><td>用途、限制、示例代码、许可</td></tr><tr><td><strong>Files and versions</strong></td><td>有哪些文件、多大——<strong>下载前必看</strong></td></tr><tr><td><strong>右栏的标签</strong></td><td>任务类型、语言、许可证、参数量</td></tr><tr><td><strong>Community</strong></td><td>别人踩过的坑，常有关键信息</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>许可证要真的看一眼。</strong> Hub 上的模型许可差异很大：</p><ul><li><strong>Apache-2.0 / MIT</strong> —— 基本随便用，包括商用。</li><li><strong>Llama 系列许可</strong> —— 商用有条件（月活门槛、命名要求）。</li><li><strong>非商业许可（CC-BY-NC 等）</strong> —— 不能商用。</li><li><strong>Gated（需申请）</strong> —— 要在页面上同意条款后才能下载，且需要登录 token。</li></ul><p>拿模型做产品之前，<strong>读一遍 LICENSE 文件</strong>，不要只看标签。</p></div><h2 id="什么是-gated-模型" tabindex="-1">什么是 gated 模型 <a class="header-anchor" href="#什么是-gated-模型" aria-label="Permalink to &quot;什么是 gated 模型&quot;">​</a></h2><p>有些模型（Llama、部分 Gemma 版本等）需要<strong>先在网页上同意条款</strong>才能下载。表现为：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>401 Client Error: Unauthorized</span></span>
<span class="line"><span>Access to model meta-llama/... is restricted. You must have access to it and be authenticated.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>解决顺序：</p><ol><li>登录网页，打开该模型页，点同意（有些要等人工批准，几分钟到几天）。</li><li>本地 <code>hf auth login</code> 登录（见<a href="/Front2Full/manual/llm/huggingface/cli-and-auth">下一步</a>）。</li><li>重新下载。</li></ol><p><strong>很多“下载报 401”的问题就是这个</strong>，而不是网络问题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HuggingFace = <strong>Hub（托管） + 库（本地用） + 付费服务</strong>，前两层免费且够用。</li><li>Hub 仓库<strong>本质是 Git</strong>——有历史、分支、tag；<strong>生产环境要钉住 commit hash</strong>。</li><li>库各管一段：<strong>只下文件用 <code>huggingface_hub</code>，别拖进 <code>transformers</code></strong>。</li><li>模型页先看 <strong>Files and versions</strong> 和<strong>许可证</strong>。</li><li>报 401 多半是 <strong>gated 模型没同意条款</strong>，不是网络问题。</li></ul><p>下一篇：<a href="/Front2Full/manual/llm/huggingface/repo-anatomy">一个模型仓库里有什么</a>。</p>`,39)])])}const k=a(e,[["render",l]]);export{c as __pageData,k as default};
